head.script:
scwin.checktype = function() {
    return typeof log;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일(wframe_SKT-309_(WSQ-947)_main.xml)을 실행한다.
    //1. Execute the sample file (wframe_SKT-309_ (WSQ-947) _main.xml).
    //Verify step 1. The call window called "scwin.test call success" is displayed normally.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "string");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'swin.test call success'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
